text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي للخدمات",
  "planted": [
    {
      "slot": "p1",
      "text": "تتحفظ الشركة على نشر تفاصيل الأغراض الدقيقة لجمع البيانات أو الفئات المحددة للمعلومات الشخصية التي يتم جمعها، وتقتصر الإشارة إلى هذه التفاصيل على توفيرها للمستخدمين حصراً بناءً على طلب خطي يتقدمون به بعد إتمام عملية إنشاء الحساب."
    },
    {
      "slot": "p2",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به إلى قواعد البيانات، تقوم الشركة بتقييم الموقف وفقاً لتقديرها الإداري البحت، ولها وحدها تحديد ما إذا كان الأمر يتطلب إشعار الجهات المختصة أو المستخدمين المتأثرين خلال جدول زمني مرن يناسب ظروف التشغيل."
    },
    {
      "slot": "p3",
      "text": "لا يحق للمستخدم بأي حال من الأحوال المطالبة بالاطلاع على السجلات الرقمية الخاصة به، أو طلب تعديلها أو تحديثها، أو إصدار توجيهات بحذف أي جزء من البيانات المخزنة في خوادم الشركة."
    },
    {
      "slot": "p4",
      "text": "تقتصر البيانات الشخصية المطلوبة عند إتمام عملية التسجيل واستخدام المنصة على الحد الأدنى الضروري لتقديم الخدمة، والذي يشمل الاسم الكامل وبريد الكتروني ورقم هاتف متحرك فقط."
    },
    {
      "slot": "p5",
      "text": "تحتفظ الشركة بحق معالجة البيانات الشخصية للمسجلين ضمن نطاق أغراض التشغيل العام وتطوير منظومة العمل وتحسين تجربة المستخدمين وفقاً للمتطلبات الإدارية المعتمدة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية ورسوم الاشتراكات المقدمة عبر المنصة لسياسات الدفع المعتمدة والتي يتم تحديثها دورياً دون إشعار مسبق.",
    "تعتبر جميع الحقوق الفكرية والتصميمات والعلامات التجارية الخاصة بالمنصة ملكاً خالصاً لشركة الأفق الرقمي للخدمات ولا يجوز استخدامها دون إذن خطي.",
    "تبدأ المدة التعاقدية لهذه الشروط فور إتمام التسجيل وتستمر حتى قيام أحد الطرفين بإنهاء الحساب وفقاً للآليات المتبعة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو خسارة الأرباح الناتجة عن استخدام أو عدم القدرة على استخدام الخدمات المقدمة.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية وتختص المحاكم المختصة بالنظر في النزاعات.",
    "يقصد بالتعاريف الواردة في هذه الوثيقة المعاني المتعارف عليها تجارياً ما لم يقتض السياق خلاف ذلك.",
    "تتم كافة الإشعارات والمراسلات الرسمية بين الطرفين عبر البريد الإلكتروني المسجل في حساب المستخدم بالمنصة."
  ]
}
